css:
* { box-sizing: border-box; }
body { margin: 0; background: #f6f5f0; color: #223c34; font-family: Arial, sans-serif; font-size: 15px; line-height: 1.5; }
a { color: #24483b; text-underline-offset: 4px; }
.topbar { max-width: 1080px; margin: 0 auto; padding: 18px 24px; display: flex; justify-content: space-between; gap: 20px; border-bottom: 1px solid #cfd8cd; }
main { max-width: 1080px; margin: 0 auto; padding: 0 24px; }
.intro { padding: 30px 0 26px; }
.eyebrow { margin: 0 0 10px; font-size: 11px; font-weight: 700; letter-spacing: 1.8px; text-transform: uppercase; color: #7d543c; }
h1 { margin: 0 0 12px; font-size: 48px; line-height: 1.08; letter-spacing: -1px; }
h2 { margin: 0 0 12px; font-size: 24px; line-height: 1.2; }
p { margin: 0 0 14px; }
.lead { font-size: 18px; max-width: 740px; }
.status { display: inline-block; margin: 2px 0 18px; padding: 8px 12px; background: #e1ead9; border: 1px solid #bdcfb4; font-size: 13px; }
.jump { display: flex; flex-wrap: wrap; gap: 8px 20px; font-size: 13px; }
.tests { display: grid; grid-template-columns: 1fr 1fr; gap: 18px; }
.test { min-width: 0; padding: 24px; border: 1px solid #cad3c7; background: #fff; scroll-margin-top: 18px; }
.test-wide { grid-column: 1 / -1; }
.sample { padding: 18px; margin: 18px 0; border: 1px solid #c4d1bf; background: #f4f6ef; font-size: 21px; line-height: 1.55; overflow-wrap: anywhere; user-select: text; }
.sample::selection, .sample *::selection { background: #e5b36c; color: #153c32; }
.reading { max-width: 760px; font-size: 20px; }
.reading p { margin-bottom: 14px; }
.reading p:last-child { margin-bottom: 0; }
.caption { margin: 10px 0 5px; color: #67786c; font-size: 12px; }
.caption + .sample { margin-top: 0; }
.tray { min-height: 52px; padding: 12px 18px; border: 1px dashed #b5c3ae; color: #53664d; font-size: 17px; }
.wrapped { background: #f2dbb6; border: 1px solid #b57c42; padding: 1px 4px; }
.actions { display: flex; flex-wrap: wrap; gap: 8px; margin: 18px 0; }
button { display: inline-block; padding: 9px 12px; border: 1px solid #24483b; background: #24483b; color: #fff; font: inherit; font-size: 14px; cursor: pointer; }
button:hover { background: #376353; }
button.secondary { color: #24483b; background: #f5f6f0; }
button.secondary:hover { background: #e8eddf; }
button:focus-visible, a:focus-visible { outline: 2px solid #b6643e; outline-offset: 3px; }
.result { margin: 0; padding: 12px; background: #eef2e7; border-left: 3px solid #9bad8f; overflow-wrap: anywhere; white-space: pre-line; font-size: 14px; }
.hint { margin: 12px 0 0; color: #627269; font-size: 13px; }
footer { padding: 28px 0 32px; color: #667468; font-size: 13px; }
@media (max-width: 720px) { .tests { grid-template-columns: 1fr; } .test-wide { grid-column: auto; } h1 { font-size: 38px; } .test { padding: 20px; } }
@media (max-width: 400px) { main, .topbar { padding-left: 14px; padding-right: 14px; } .topbar { font-size: 13px; } h1 { font-size: 33px; } .sample { font-size: 19px; padding: 14px; } }
